			float o6ZGR = a6ZGR[c6ZGR-((c6ZGR > d6ZG)?d6ZG+1:0)];
			
			//-------- five
			
			a6ZFL[c6ZFL] = ((o6YL*2.0f) - (o6ZAL + o6ZBL + o6ZCL + o6ZDL + o6ZEL));
