			a6ZHL[c6ZHL] = ((o6ZBL*2.0f) - (o6YL + o6ZAL + o6ZCL + o6ZDL + o6ZEL));
			a6ZIL[c6ZIL] = ((o6ZCL*2.0f) - (o6YL + o6ZAL + o6ZBL + o6ZDL + o6ZEL));
